<script setup lang="ts">
import { computed } from 'vue';import { Activity, ArrowDown, ArrowUp, Cpu, HardDrive, MemoryStick } from 'lucide-vue-next';import type { Metrics, MetricsSample } from '@/api';import MetricChart from '@/components/MetricChart.vue';
const props=defineProps<{metrics:Metrics|null;history:Partial<MetricsSample>[];error:string}>();const percent=(used:number,total:number)=>total>0?Math.min(100,Math.max(0,used/total*100)):0;const memory=computed(()=>props.metrics?percent(props.metrics.mem_total_kb-props.metrics.mem_avail_kb,props.metrics.mem_total_kb):0);const disk=computed(()=>props.metrics?percent(props.metrics.disk_used_kb,props.metrics.disk_total_kb):0);const size=(kb:number)=>kb>=1048576?(kb/1048576).toFixed(1)+' GB':Math.round(kb/1024)+' MB';const rate=(bytes:number)=>bytes>=1048576?(bytes/1048576).toFixed(1)+' MB/s':bytes>=1024?(bytes/1024).toFixed(1)+' KB/s':Math.round(bytes)+' B/s';const uptime=computed(()=>{const s=props.metrics?.uptime_secs??0;const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);return d?d+' 天 '+h+' 小时':h+' 小时 '+m+' 分'});
</script>
<template><section class="performance-overview" aria-label="运行监控"><div class="overview-heading"><div class="flex items-center gap-2"><Activity class="h-4 w-4 text-primary"/><h2 class="text-sm font-semibold">运行监控</h2><span class="live-indicator" :class="{stale:error}">{{error?'更新中断':metrics?'实时':'采集中'}}</span></div><span class="text-xs text-muted-foreground">{{metrics?metrics.cores+' 核 · 已运行 '+uptime:'等待首次采样'}}</span></div><p v-if="error" class="mb-3 text-xs text-destructive" role="status">{{error}}</p><div class="metric-grid"><article class="metric-tile metric-cpu"><div class="metric-label"><span>CPU</span><Cpu class="h-4 w-4"/></div><div class="metric-value">{{metrics?Math.round(metrics.cpu_pct):'—'}}<small v-if="metrics">%</small></div><MetricChart :samples="history" mode="cpu"/></article><article class="metric-tile metric-memory"><div class="metric-label"><span>内存</span><MemoryStick class="h-4 w-4"/></div><div class="metric-value">{{metrics?.mem_total_kb?Math.round(memory):'—'}}<small v-if="metrics?.mem_total_kb">%</small></div><div class="metric-track"><div :style="{width:memory+'%'}"/></div><p class="metric-detail">{{metrics?.mem_total_kb?size(metrics.mem_total_kb-metrics.mem_avail_kb)+' / '+size(metrics.mem_total_kb):'等待采样'}}</p></article><article class="metric-tile metric-disk"><div class="metric-label"><span>系统磁盘</span><HardDrive class="h-4 w-4"/></div><div class="metric-value">{{metrics?.disk_total_kb?Math.round(disk):'—'}}<small v-if="metrics?.disk_total_kb">%</small></div><div class="metric-track"><div :style="{width:disk+'%'}"/></div><p class="metric-detail">{{metrics?.disk_total_kb?size(metrics.disk_used_kb)+' / '+size(metrics.disk_total_kb):'等待采样'}}</p></article><article class="metric-tile metric-network"><div class="metric-label"><span>实时流量</span><Activity class="h-4 w-4"/></div><div class="network-rate"><ArrowDown class="h-3.5 w-3.5"/><strong>{{metrics?rate(metrics.rx_bps):'—'}}</strong></div><div class="network-rate"><ArrowUp class="h-3.5 w-3.5"/><strong>{{metrics?rate(metrics.tx_bps):'—'}}</strong></div><p class="metric-detail">下行 / 上行</p></article></div><div class="metric-footer"><span>负载 1 / 5 / 15 分钟 <b>{{metrics&&metrics.load1>=0?[metrics.load1,metrics.load5,metrics.load15].map(n=>n.toFixed(2)).join(' / '):'—'}}</b></span><span>面板占用 <b>{{metrics?size(metrics.panel_rss_kb):'—'}}</b></span><span>每 3 秒更新</span></div></section></template>
